import{_ as a,o as t,c as e,a2 as n}from"./chunks/framework.DnrXFDHb.js";const g=JSON.parse('{"title":"附录 B：损失函数速查表","description":"","frontmatter":{},"headers":[],"relativePath":"chapters/appendix-b-loss-cheatsheet.md","filePath":"chapters/appendix-b-loss-cheatsheet.md"}'),o={name:"chapters/appendix-b-loss-cheatsheet.md"};function i(l,s,p,d,r,c){return t(),e("div",null,[...s[0]||(s[0]=[n(`<h1 id="附录-b-损失函数速查表" tabindex="-1">附录 B：损失函数速查表 <a class="header-anchor" href="#附录-b-损失函数速查表" aria-label="Permalink to &quot;附录 B：损失函数速查表&quot;">​</a></h1><h2 id="b-1-语言模型损失" tabindex="-1">B.1 语言模型损失 <a class="header-anchor" href="#b-1-语言模型损失" aria-label="Permalink to &quot;B.1 语言模型损失&quot;">​</a></h2><h3 id="customcrossentropyloss" tabindex="-1">CustomCrossEntropyLoss <a class="header-anchor" href="#customcrossentropyloss" aria-label="Permalink to &quot;CustomCrossEntropyLoss&quot;">​</a></h3><p><strong>用途</strong>：标准语言模型训练</p><p><strong>公式</strong>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>loss = -sum(log_softmax(logits) * labels) / num_items_in_batch</span></span></code></pre></div><p><strong>适用场景</strong>：</p><ul><li>SFT 训练</li><li>预训练</li></ul><p><strong>参数</strong>：</p><ul><li><code>num_items_in_batch</code>：批次中的 token 数</li></ul><hr><h2 id="b-2-嵌入学习损失" tabindex="-1">B.2 嵌入学习损失 <a class="header-anchor" href="#b-2-嵌入学习损失" aria-label="Permalink to &quot;B.2 嵌入学习损失&quot;">​</a></h2><h3 id="cosinesimilarityloss" tabindex="-1">CosineSimilarityLoss <a class="header-anchor" href="#cosinesimilarityloss" aria-label="Permalink to &quot;CosineSimilarityLoss&quot;">​</a></h3><p><strong>用途</strong>：句子对相似度回归</p><p><strong>公式</strong>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>loss = MSE(cosine_similarity(sent1, sent2), labels)</span></span></code></pre></div><p><strong>适用场景</strong>：</p><ul><li>STS（语义文本相似度）任务</li><li>标签为 0-5 的相似度分数</li></ul><p><strong>超参数</strong>：</p><ul><li>无特殊超参数</li></ul><hr><h3 id="contrastiveloss" tabindex="-1">ContrastiveLoss <a class="header-anchor" href="#contrastiveloss" aria-label="Permalink to &quot;ContrastiveLoss&quot;">​</a></h3><p><strong>用途</strong>：对比学习</p><p><strong>公式</strong>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>d = cosine_distance(sent1, sent2)</span></span>
<span class="line"><span>loss = 0.5 * (y * d^2 + (1-y) * max(0, margin-d)^2)</span></span></code></pre></div><p><strong>适用场景</strong>：</p><ul><li>句子对分类任务</li><li>标签为 0（不相似）或 1（相似）</li></ul><p><strong>超参数</strong>：</p><ul><li><code>margin</code>：0.5（硬编码）</li></ul><hr><h3 id="onlinecontrastiveloss" tabindex="-1">OnlineContrastiveLoss <a class="header-anchor" href="#onlinecontrastiveloss" aria-label="Permalink to &quot;OnlineContrastiveLoss&quot;">​</a></h3><p><strong>用途</strong>：在线对比学习（困难样本挖掘）</p><p><strong>公式</strong>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>negs = distances[labels == 0]</span></span>
<span class="line"><span>poss = distances[labels == 1]</span></span>
<span class="line"><span>hard_negs = negs[negs &lt; max(poss)]</span></span>
<span class="line"><span>hard_poss = poss[poss &gt; min(negs)]</span></span>
<span class="line"><span>loss = sum(hard_poss^2) + sum(relu(margin - hard_negs)^2)</span></span></code></pre></div><p><strong>适用场景</strong>：</p><ul><li>数据分布不均衡</li><li>自动聚焦困难样本</li></ul><p><strong>超参数</strong>：</p><ul><li><code>margin</code>：0.5（硬编码）</li></ul><hr><h3 id="infonceloss" tabindex="-1">InfoNCELoss <a class="header-anchor" href="#infonceloss" aria-label="Permalink to &quot;InfoNCELoss&quot;">​</a></h3><p><strong>用途</strong>：多负样本检索</p><p><strong>公式</strong>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>sim_matrix = (sentences @ sentences.T) / temperature</span></span>
<span class="line"><span>loss = CrossEntropy(sim_matrix, labels)</span></span></code></pre></div><p><strong>适用场景</strong>：</p><ul><li>检索任务（如 MS MARCO）</li><li>嵌入模型训练（如 BGE、E5）</li></ul><p><strong>超参数</strong>（环境变量）：</p><ul><li><code>INFONCE_TEMPERATURE</code>：0.1（温度参数）</li><li><code>INFONCE_USE_BATCH</code>：True（是否使用批内负样本）</li><li><code>INFONCE_HARD_NEGATIVES</code>：None（硬负样本数量）</li><li><code>INFONCE_MASK_FAKE_NEGATIVE</code>：False（是否屏蔽假负样本）</li><li><code>INFONCE_FAKE_NEG_MARGIN</code>：0.1（假负样本阈值）</li><li><code>INFONCE_INCLUDE_QQ</code>：False（是否加入 q-q 相似度）</li><li><code>INFONCE_INCLUDE_DD</code>：False（是否加入 d-d 相似度）</li></ul><hr><h2 id="b-3-重排损失" tabindex="-1">B.3 重排损失 <a class="header-anchor" href="#b-3-重排损失" aria-label="Permalink to &quot;B.3 重排损失&quot;">​</a></h2><h3 id="pointwisererankerloss" tabindex="-1">PointwiseRerankerLoss <a class="header-anchor" href="#pointwisererankerloss" aria-label="Permalink to &quot;PointwiseRerankerLoss&quot;">​</a></h3><p><strong>用途</strong>：点式重排</p><p><strong>公式</strong>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>loss = BCEWithLogits(logits, labels)</span></span></code></pre></div><p><strong>适用场景</strong>：</p><ul><li>简单排序任务</li><li>二分类场景</li></ul><p><strong>超参数</strong>：</p><ul><li>无特殊超参数</li></ul><hr><h3 id="listwisererankerloss" tabindex="-1">ListwiseRerankerLoss <a class="header-anchor" href="#listwisererankerloss" aria-label="Permalink to &quot;ListwiseRerankerLoss&quot;">​</a></h3><p><strong>用途</strong>：列表式重排</p><p><strong>公式</strong>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>for each group:</span></span>
<span class="line"><span>    scaled_logits = logits / temperature</span></span>
<span class="line"><span>    loss += CrossEntropy(scaled_logits, target=0)</span></span>
<span class="line"><span>loss = mean(losses)</span></span></code></pre></div><p><strong>适用场景</strong>：</p><ul><li>精确排序</li><li>考虑文档间相对关系</li></ul><p><strong>超参数</strong>（环境变量）：</p><ul><li><code>LISTWISE_RERANKER_TEMPERATURE</code>：1.0（温度参数）</li><li><code>LISTWISE_RERANKER_MIN_GROUP_SIZE</code>：2（最小组大小）</li></ul><hr><h2 id="b-4-dpo-损失变体" tabindex="-1">B.4 DPO 损失变体 <a class="header-anchor" href="#b-4-dpo-损失变体" aria-label="Permalink to &quot;B.4 DPO 损失变体&quot;">​</a></h2><h3 id="sigmoid-默认" tabindex="-1">sigmoid（默认） <a class="header-anchor" href="#sigmoid-默认" aria-label="Permalink to &quot;sigmoid（默认）&quot;">​</a></h3><p><strong>公式</strong>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>losses = -log(sigmoid(beta * logits))</span></span></code></pre></div><p><strong>特点</strong>：标准 DPO，最稳定</p><hr><h3 id="hinge" tabindex="-1">hinge <a class="header-anchor" href="#hinge" aria-label="Permalink to &quot;hinge&quot;">​</a></h3><p><strong>公式</strong>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>losses = relu(1 - beta * logits)</span></span></code></pre></div><p><strong>特点</strong>：更关注难样本</p><hr><h3 id="ipo" tabindex="-1">ipo <a class="header-anchor" href="#ipo" aria-label="Permalink to &quot;ipo&quot;">​</a></h3><p><strong>公式</strong>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>losses = (logits - 1/(2*beta))^2</span></span></code></pre></div><p><strong>特点</strong>：避免 DPO 过拟合</p><hr><h3 id="exo-pair" tabindex="-1">exo_pair <a class="header-anchor" href="#exo-pair" aria-label="Permalink to &quot;exo_pair&quot;">​</a></h3><p><strong>公式</strong>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>losses = sigmoid(beta*logits) * (log_sigmoid(beta*logits) - log(1-label_smoothing)) + </span></span>
<span class="line"><span>         sigmoid(-beta*logits) * (log_sigmoid(-beta*logits) - log(label_smoothing))</span></span></code></pre></div><p><strong>特点</strong>：指数加权</p><hr><h3 id="bco-pair" tabindex="-1">bco_pair <a class="header-anchor" href="#bco-pair" aria-label="Permalink to &quot;bco_pair&quot;">​</a></h3><p><strong>公式</strong>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>chosen_rewards = beta * (chosen_logps - ref_chosen_logps)</span></span>
<span class="line"><span>rejected_rewards = beta * (rejected_logps - ref_rejected_logps)</span></span>
<span class="line"><span>delta = running_mean(rewards)</span></span>
<span class="line"><span>losses = -log_sigmoid(chosen_rewards - delta) - log_sigmoid(-(rejected_rewards - delta))</span></span></code></pre></div><p><strong>特点</strong>：使用运行均值</p><hr><h3 id="sppo-hard" tabindex="-1">sppo_hard <a class="header-anchor" href="#sppo-hard" aria-label="Permalink to &quot;sppo_hard&quot;">​</a></h3><p><strong>公式</strong>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>a = chosen_logps - ref_chosen_logps</span></span>
<span class="line"><span>b = rejected_logps - ref_rejected_logps</span></span>
<span class="line"><span>losses = (a - 0.5/beta)^2 + (b + 0.5/beta)^2</span></span></code></pre></div><p><strong>特点</strong>：自博弈优化</p><hr><h3 id="nca-pair" tabindex="-1">nca_pair <a class="header-anchor" href="#nca-pair" aria-label="Permalink to &quot;nca_pair&quot;">​</a></h3><p><strong>公式</strong>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>chosen_rewards = (chosen_logps - ref_chosen_logps) * beta</span></span>
<span class="line"><span>rejected_rewards = (rejected_logps - ref_rejected_logps) * beta</span></span>
<span class="line"><span>losses = -log_sigmoid(chosen_rewards) - 0.5*log_sigmoid(-chosen_rewards) - 0.5*log_sigmoid(-rejected_rewards)</span></span></code></pre></div><p><strong>特点</strong>：噪声对比学习</p><hr><h3 id="aot-aot-unpaired" tabindex="-1">aot / aot_unpaired <a class="header-anchor" href="#aot-aot-unpaired" aria-label="Permalink to &quot;aot / aot_unpaired&quot;">​</a></h3><p><strong>公式</strong>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>sorted_delta = sort(chosen_logratios) - sort(rejected_logratios)</span></span>
<span class="line"><span>losses = -log_sigmoid(beta * sorted_delta)</span></span></code></pre></div><p><strong>特点</strong>：最优传输对齐</p><hr><h3 id="apo-zero-apo-down" tabindex="-1">apo_zero / apo_down <a class="header-anchor" href="#apo-zero-apo-down" aria-label="Permalink to &quot;apo_zero / apo_down&quot;">​</a></h3><p><strong>公式</strong>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># apo_zero</span></span>
<span class="line"><span>losses = (1 - sigmoid(beta*chosen_logratios)) + sigmoid(beta*rejected_logratios)</span></span>
<span class="line"><span></span></span>
<span class="line"><span># apo_down</span></span>
<span class="line"><span>losses = sigmoid(beta*chosen_logratios) + (1 - sigmoid(beta*(chosen_logratios-rejected_logratios)))</span></span></code></pre></div><p><strong>特点</strong>：自适应优化</p><hr><h3 id="discopop" tabindex="-1">discopop <a class="header-anchor" href="#discopop" aria-label="Permalink to &quot;discopop&quot;">​</a></h3><p><strong>公式</strong>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>logits = logits * beta</span></span>
<span class="line"><span>log_ratio_modulation = sigmoid(logits / discopop_tau)</span></span>
<span class="line"><span>logistic_component = -log_sigmoid(logits)</span></span>
<span class="line"><span>exp_component = exp(-logits)</span></span>
<span class="line"><span>losses = logistic_component * (1 - log_ratio_modulation) + exp_component * log_ratio_modulation</span></span></code></pre></div><p><strong>特点</strong>：双组件加权</p><hr><h3 id="robust" tabindex="-1">robust <a class="header-anchor" href="#robust" aria-label="Permalink to &quot;robust&quot;">​</a></h3><p><strong>公式</strong>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>losses = (-log_sigmoid(beta*logits) * (1-label_smoothing) + </span></span>
<span class="line"><span>          log_sigmoid(-beta*logits) * label_smoothing) / (1 - 2*label_smoothing)</span></span></code></pre></div><p><strong>特点</strong>：标签平滑</p><hr><h3 id="sft" tabindex="-1">sft <a class="header-anchor" href="#sft" aria-label="Permalink to &quot;sft&quot;">​</a></h3><p><strong>公式</strong>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>losses = nll_loss</span></span></code></pre></div><p><strong>特点</strong>：SFT 辅助损失</p><hr><h2 id="b-5-奖励模型损失" tabindex="-1">B.5 奖励模型损失 <a class="header-anchor" href="#b-5-奖励模型损失" aria-label="Permalink to &quot;B.5 奖励模型损失&quot;">​</a></h2><h3 id="reward-model-loss" tabindex="-1">Reward Model Loss <a class="header-anchor" href="#reward-model-loss" aria-label="Permalink to &quot;Reward Model Loss&quot;">​</a></h3><p><strong>公式</strong>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>if margin is not None:</span></span>
<span class="line"><span>    loss = -log_sigmoid(rewards_chosen - rewards_rejected - margin)</span></span>
<span class="line"><span>else:</span></span>
<span class="line"><span>    loss = -log_sigmoid(rewards_chosen - rewards_rejected)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>if center_rewards_coefficient is not None:</span></span>
<span class="line"><span>    loss += center_rewards_coefficient * mean((rewards_chosen + rewards_rejected)^2)</span></span></code></pre></div><p><strong>适用场景</strong>：</p><ul><li>奖励模型训练</li><li>PPO 前置步骤</li></ul><p><strong>超参数</strong>：</p><ul><li><code>center_rewards_coefficient</code>：None（推荐 0.01）</li></ul><hr><h2 id="b-6-gkd-损失" tabindex="-1">B.6 GKD 损失 <a class="header-anchor" href="#b-6-gkd-损失" aria-label="Permalink to &quot;B.6 GKD 损失&quot;">​</a></h2><h3 id="jsd-loss" tabindex="-1">JSD Loss <a class="header-anchor" href="#jsd-loss" aria-label="Permalink to &quot;JSD Loss&quot;">​</a></h3><p><strong>公式</strong>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>if beta == 0:</span></span>
<span class="line"><span>    jsd = KL(student || teacher)  # forward KL</span></span>
<span class="line"><span>elif beta == 1:</span></span>
<span class="line"><span>    jsd = KL(teacher || student)  # reverse KL</span></span>
<span class="line"><span>else:</span></span>
<span class="line"><span>    m = beta * teacher + (1-beta) * student</span></span>
<span class="line"><span>    jsd = beta * KL(m || teacher) + (1-beta) * KL(m || student)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>loss = jsd + sft_alpha * sft_loss</span></span></code></pre></div><p><strong>适用场景</strong>：</p><ul><li>知识蒸馏</li><li>模型压缩</li></ul><p><strong>超参数</strong>：</p><ul><li><code>beta</code>：0.5（JSD 插值参数）</li><li><code>temperature</code>：0.9（温度缩放）</li><li><code>sft_alpha</code>：0.0（SFT 损失权重）</li></ul><hr><h2 id="b-7-损失函数选择指南" tabindex="-1">B.7 损失函数选择指南 <a class="header-anchor" href="#b-7-损失函数选择指南" aria-label="Permalink to &quot;B.7 损失函数选择指南&quot;">​</a></h2><h3 id="按任务类型选择" tabindex="-1">按任务类型选择 <a class="header-anchor" href="#按任务类型选择" aria-label="Permalink to &quot;按任务类型选择&quot;">​</a></h3><table tabindex="0"><thead><tr><th>任务类型</th><th>推荐损失</th><th>说明</th></tr></thead><tbody><tr><td>SFT</td><td>CrossEntropy</td><td>标准语言模型损失</td></tr><tr><td>DPO</td><td>sigmoid</td><td>最稳定的 DPO 变体</td></tr><tr><td>CPO/SimPO</td><td>cpo/simpo</td><td>无需参考模型</td></tr><tr><td>嵌入学习</td><td>InfoNCE</td><td>支持批内负样本</td></tr><tr><td>重排</td><td>ListwiseReranker</td><td>考虑文档间关系</td></tr><tr><td>知识蒸馏</td><td>JSD</td><td>GKD 标准损失</td></tr></tbody></table><h3 id="按场景选择" tabindex="-1">按场景选择 <a class="header-anchor" href="#按场景选择" aria-label="Permalink to &quot;按场景选择&quot;">​</a></h3><table tabindex="0"><thead><tr><th>场景</th><th>推荐损失</th><th>说明</th></tr></thead><tbody><tr><td>标准对齐</td><td>DPO sigmoid</td><td>最稳定</td></tr><tr><td>避免过拟合</td><td>DPO ipo</td><td>平方损失</td></tr><tr><td>难样本</td><td>DPO hinge</td><td>关注困难样本</td></tr><tr><td>噪声数据</td><td>DPO robust</td><td>标签平滑</td></tr><tr><td>检索任务</td><td>InfoNCE</td><td>批内负样本</td></tr><tr><td>精确排序</td><td>ListwiseReranker</td><td>列表级对比</td></tr></tbody></table><hr><h2 id="b-8-损失函数对比表" tabindex="-1">B.8 损失函数对比表 <a class="header-anchor" href="#b-8-损失函数对比表" aria-label="Permalink to &quot;B.8 损失函数对比表&quot;">​</a></h2><table tabindex="0"><thead><tr><th>损失函数</th><th>计算复杂度</th><th>显存占用</th><th>训练速度</th><th>效果</th></tr></thead><tbody><tr><td>CrossEntropy</td><td>低</td><td>低</td><td>快</td><td>基线</td></tr><tr><td>CosineSimilarity</td><td>低</td><td>低</td><td>快</td><td>回归任务</td></tr><tr><td>Contrastive</td><td>中</td><td>中</td><td>中</td><td>基线</td></tr><tr><td>OnlineContrastive</td><td>中</td><td>中</td><td>中</td><td>困难样本</td></tr><tr><td>InfoNCE</td><td>高</td><td>高</td><td>慢</td><td>最佳</td></tr><tr><td>PointwiseReranker</td><td>低</td><td>低</td><td>快</td><td>简单排序</td></tr><tr><td>ListwiseReranker</td><td>中</td><td>中</td><td>中</td><td>精确排序</td></tr><tr><td>DPO sigmoid</td><td>中</td><td>中（2倍模型）</td><td>中</td><td>好</td></tr><tr><td>DPO ipo</td><td>中</td><td>中</td><td>中</td><td>好</td></tr><tr><td>JSD</td><td>中</td><td>中（2倍模型）</td><td>中</td><td>好</td></tr></tbody></table>`,154)])])}const b=a(o,[["render",i]]);export{g as __pageData,b as default};
